True def transform(grid):
    n = len(grid[0])
    center = grid[0].index(2)
    out = []
    for r in range(n):
        row = [0] * n
        for c in range(n):
            if abs(c - center) == r:
                row[c] = 2
            elif r >= 3 and abs(c - center) < r and (c - center - r) % 4 == 0:
                row[c] = 1
        out.append(row)
    return out
